function reset(){elapsed=0;inventoryOpen=false;needDamageTimer=0;searchedCount=0;inventoryDirty=true;Object.assign(player,{x:460,y:1480,hp:100,rad:8,hunger:82,thirst:76,ammo:30,reserve:90,medkits:2,water:2,food:2,artifacts:0,shootCd:0,invuln:0,ru:1240,walkPhase:0,moving:false});artifact.found=false;stash.forEach(s=>s.searched=false);enemies.forEach(e=>{e.hp=e.name==='bloodsucker'?90:e.name==='flesh'?68:e.name==='snork'?55:e.name==='pseudodog'?52:e.type==='mutant'?55:65;e.dead=false;e.state='patrol';e.alert=0;e.attackCd=0});civilians.forEach(n=>{n.walkPhase=0;n.moving=false});bullets.length=0;fx.length=0;dead=won=paused=false;$('location-name').textContent='СКАДОВСК';$('end-overlay').classList.add('hidden');$('pause-overlay').classList.add('hidden');$('inventory-panel').classList.add('hidden');$('interaction-prompt').classList.remove('visible');$('mission-title').textContent='Зона не прощает спешки';$('mission-copy').textContent='Ищи припасы, следи за состоянием и возвращайся в лагерь до темноты.';$('mission-progress-bar').style.width='8%';$('cache-count').textContent='0';$('survival-label').textContent='В ПУТИ';$('medkit-count').textContent='2';$('water-count').textContent='2';$('food-count').textContent='2';updateUI()}
$('start-button').onclick=start;$('resume-button').onclick=()=>{paused=false;$('pause-overlay').classList.add('hidden');last=performance.now()};$('pause-button').onclick=()=>togglePause();$('restart-button').onclick=()=>{reset();start()};$('again-button').onclick=()=>{reset();start()};$('sound-button').onclick=()=>{$('sound-button').classList.toggle('muted');muted=!muted;toast(muted?'ЗВУК ВЫКЛЮЧЕН':'ЗВУК ВКЛЮЧЁН');audio(400,.06,'sine')};
function togglePause(){if(!gameStarted||dead||won)return;paused=!paused;$('pause-overlay').classList.toggle('hidden',!paused);if(!paused)last=performance.now()}
addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(e.repeat)return;if(k==='escape'&&inventoryOpen){toggleInventory(false);return}if(k==='escape'||k==='p')togglePause();if(k==='e')interact();if(k==='r')reload();if(k==='i')toggleInventory();if(k==='1')select(1);if(k==='2')select(2);if(k==='3')select(3);if(k==='4')select(4)});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('mousemove',e=>{let rect=canvas.getBoundingClientRect();mouse.x=(e.clientX-rect.left)*cw/rect.width;mouse.y=(e.clientY-rect.top)*ch/rect.height;mouse.active=true});canvas.addEventListener('mousedown',e=>{if(e.button===0){mouse.down=true;mouse.active=true}});addEventListener('mouseup',e=>{if(e.button===0)mouse.down=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function select(n){document.querySelectorAll('.hotbar-slot').forEach((el,i)=>el.classList.toggle('selected',i===n-1));if(!gameStarted||paused)return;if(n===2)useMedkit();if(n===3)useWater();if(n===4)useFood()}
function toggleInventory(force){if(!gameStarted||paused)return;inventoryOpen=typeof force==='boolean'?force:!inventoryOpen;$('inventory-panel').classList.toggle('hidden',!inventoryOpen);if(inventoryOpen){inventoryDirty=true;renderInventory()}}
$('inventory-button').addEventListener('click',()=>toggleInventory());$('inventory-close').addEventListener('click',()=>toggleInventory(false));document.querySelectorAll('.hotbar-slot').forEach((el,i)=>el.addEventListener('click',()=>select(i+1)));
function reload(){if(player.ammo>=30||player.reserve<=0){toast(player.reserve<=0?'НЕТ ЗАПАСНЫХ ПАТРОНОВ':'МАГАЗИН ПОЛОН');return}let n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;inventoryDirty=true;toast('ПЕРЕЗАРЯЖЕНО · '+n+' ПАТРОНОВ');audio(130,.1,'triangle')}
function blockedByWorld(x,y,r){if(x<35||x>W-35||y<35||y>H-35)return true;for(let t of trees)if(Math.hypot(x-t.x,y-t.y)<r+t.r*.62)return true;for(let b of buildings){let dx=x-b.x,dy=y-b.y,c=Math.cos(-b.r),s=Math.sin(-b.r),lx=dx*c-dy*s,ly=dx*s+dy*c;if(Math.abs(lx)<b.w/2+r&&Math.abs(ly)<b.h/2+r)return true}return false}
function actorBlocked(entity,x,y,r){if(entity!==player&&Math.hypot(x-player.x,y-player.y)<r+player.r)return true;for(let a of enemies.concat(civilians)){if(a===entity||a.dead)continue;if(Math.hypot(x-a.x,y-a.y)<r+(a.r||11))return true}return false}
function moveActor(entity,dx,dy,r){let ox=entity.x,oy=entity.y,nx=clamp(ox+dx,35,W-35),ny=clamp(oy+dy,35,H-35);if(!blockedByWorld(nx,oy,r)&&!actorBlocked(entity,nx,oy,r))entity.x=nx;if(!blockedByWorld(entity.x,ny,r)&&!actorBlocked(entity,entity.x,ny,r))entity.y=ny;entity.moving=Math.hypot(entity.x-ox,entity.y-oy)>.15;if(entity.moving)entity.walkPhase=(entity.walkPhase||0)+Math.hypot(entity.x-ox,entity.y-oy)*.11}
function inventoryWeight(){return 1+player.ammo*.015+player.reserve*.015+player.medkits*.35+player.water*.7+player.food*.35+player.artifacts*.8+2.6}
function renderInventory(){if(!inventoryOpen)return;let items=[{key:'medkit',name:'Аптечка',count:player.medkits,weight:.35,description:'Восстанавливает 38 ед. здоровья.',use:useMedkit},{key:'water',name:'Фляга воды',count:player.water,weight:.7,description:'Утоляет жажду и немного снижает радиацию.',use:useWater},{key:'food',name:'Сухой паёк',count:player.food,weight:.35,description:'Восстанавливает 42 ед. сытости.',use:useFood},{key:'ammo',name:'Патроны 7,62×39',count:player.ammo+' / '+player.reserve,weight:(player.ammo+player.reserve)*.015,description:'Текущий магазин и запас.'},{key:'artifact',name:'Артефакт',count:player.artifacts,weight:.8,description:'Ценная находка. Вернись с ней в лагерь.'}];$('inventory-list').innerHTML=items.map(item=>`<button class="inventory-item" data-item="${item.key}" ${item.use&&item.count>0?'':'disabled'}><span class="inventory-item-icon">${item.key==='medkit'?'✚':item.key==='water'?'◉':item.key==='food'?'▰':item.key==='ammo'?'⌁':'◇'}</span><span class="inventory-item-copy"><b>${item.name}</b><small>${item.description}</small></span><strong>${item.count}</strong><small class="inventory-item-weight">${item.weight.toFixed(1)} кг</small></button>`).join('');$('inventory-list').querySelectorAll('[data-item]').forEach(button=>button.addEventListener('click',()=>{let item=items.find(entry=>entry.key===button.dataset.item);item?.use?.();inventoryDirty=true;renderInventory()}));let weight=inventoryWeight();$('inventory-weight').textContent=`${weight.toFixed(1)} / 26 КГ`;$('weight-bar').style.width=`${Math.min(100,weight/26*100)}%`;inventoryDirty=false}
function useMedkit(){if(!gameStarted||paused)return;if(player.medkits<=0){toast('АПТЕЧЕК НЕТ');return}if(player.hp>=100){toast('ЗДОРОВЬЕ В НОРМЕ');return}player.medkits--;player.hp=Math.min(100,player.hp+38);inventoryDirty=true;toast('АПТЕЧКА ИСПОЛЬЗОВАНА · +38 ЗДОРОВЬЯ');audio(520,.16,'sine');updateUI()}
function useWater(){if(!gameStarted||paused)return;if(player.water<=0){toast('ВОДА ЗАКОНЧИЛАСЬ');return}if(player.thirst>=100&&player.rad<=0){toast('ПИТЬ НЕ ХОЧЕТСЯ');return}player.water--;player.thirst=Math.min(100,player.thirst+45);player.rad=Math.max(0,player.rad-8);inventoryDirty=true;toast('ВОДА ВЫПИТА · ЖАЖДА УТОЛЕНА');audio(520,.16,'sine');updateUI()}
function useFood(){if(!gameStarted||paused)return;if(player.food<=0){toast('ПАЙКИ ЗАКОНЧИЛИСЬ');return}if(player.hunger>=100){toast('ТЫ УЖЕ СЫТ');return}player.food--;player.hunger=Math.min(100,player.hunger+42);inventoryDirty=true;toast('ПАЁК СЪЕДЕН · СЫТОСТЬ ВОССТАНОВЛЕНА');audio(440,.16,'sine');updateUI()}
function safeTeleport(point){const candidates=[{x:point.x,y:point.y}];for(let radius=18;radius<=108;radius+=18)for(let i=0;i<12;i++){let a=i*Math.PI/6;candidates.push({x:point.x+Math.cos(a)*radius,y:point.y+Math.sin(a)*radius})}let spot=candidates.find(p=>!blockedByWorld(p.x,p.y,player.r)&&!actorBlocked(player,p.x,p.y,player.r));return spot}
function interact(){if(!gameStarted||paused)return;let choices=[];for(let gate of gates){let d=dist(player,gate);if(d<110)choices.push({type:'gate',target:gate,d})}for(let person of civilians){let d=dist(player,person);if(d<68)choices.push({type:'person',target:person,d})}for(let target of stash){let d=dist(player,target);if(!target.searched&&d<74)choices.push({type:'stash',target,d})}if(!artifact.found){let d=dist(player,artifact);if(d<92)choices.push({type:'artifact',target:artifact,d})}choices.sort((a,b)=>a.d-b.d);let choice=choices[0];if(!choice){toast('ЗДЕСЬ НЕЧЕГО ДЕЛАТЬ');return}if(choice.type==='gate'){let gate=choice.target,spot=safeTeleport(gate.to);if(!spot){toast('ПУТЬ ЗАВАЛЕН · ПОПРОБУЙ ЕЩЁ РАЗ');return}player.x=spot.x;player.y=spot.y;player.moving=false;player.invuln=2.5;bullets.length=0;for(let enemy of enemies){if(!enemy.dead){enemy.state='patrol';enemy.alert=0;enemy.target=null}}camera.x=clamp(player.x-cw/2,0,W-cw);camera.y=clamp(player.y-ch/2,0,H-ch);let destination=locationName(gate.destination);toast('ПЕРЕХОД · '+destination);$('location-name').textContent=destination;audio(360,.2,'sine');return}if(choice.type==='person'){toast(choice.target.name==='Veles'?'ВЕЛЕС: Держись троп и не лезь в аномалии.':'МАКАР: Старая железная дорога полна мутантов.');return}if(choice.type==='stash'){let target=choice.target;target.searched=true;searchedCount++;let msg='НАЙДЕНО: '+(target.loot==='FIELD DRESSING'?'АПТЕЧКА':target.loot==='MEDKIT'?'АПТЕЧКА':target.loot.includes('FMJ')?'9 ПАТРОНОВ 7,62×39':'350 ₽');if(target.loot==='FIELD DRESSING'||target.loot==='MEDKIT'){player.medkits++;$('medkit-count').textContent=player.medkits}else if(target.loot.includes('FMJ'))player.reserve+=9;else if(target.loot.includes('350'))player.ru+=350;inventoryDirty=true;toast(msg);audio(620,.12,'sine');updateUI();return}artifact.found=true;player.artifacts=1;player.ru+=800;inventoryDirty=true;banner('АРТЕФАКТ НАЙДЕН · ВОЗВРАЩАЙСЯ В ЛАГЕРЬ');$('mission-title').textContent='Дорога домой';$('mission-copy').textContent='Артефакт у тебя. Вернись в Скадовск живым и получи награду.';$('survival-label').textContent='ВОЗВРАЩАЙСЯ В ЛАГЕРЬ';$('mission-progress-bar').style.width='58%';audio(820,.25,'sine');updateUI()}
function fire(){if(player.shootCd>0)return;if(player.ammo<=0){toast('МАГАЗИН ПУСТ · НАЖМИ R');player.shootCd=.28;audio(90,.05,'square',.012);return}player.ammo--;player.shootCd=.18;player.flash=.08;audio(115,.075,'sawtooth',.045);let sx=player.x+Math.cos(player.angle)*17,sy=player.y+Math.sin(player.angle)*17,spread=(Math.random()-.5)*.045,ang=player.angle+spread;bullets.push({x:sx,y:sy,vx:Math.cos(ang)*730,vy:Math.sin(ang)*730,life:.65,owner:'player',damage:26});fx.push({x:sx,y:sy,life:.12,type:'muzzle',a:ang});for(let e of enemies){if(e.dead)continue;let dx=e.x-sx,dy=e.y-sy,along=dx*Math.cos(ang)+dy*Math.sin(ang),side=Math.abs(-dx*Math.sin(ang)+dy*Math.cos(ang));if(along>0&&along<470&&side<(e.r||13)+7){e.hp-=26;e.state='alert';e.alert=5;fx.push({x:e.x,y:e.y,life:.28,type:'blood'});if(e.hp<=0){e.dead=true;player.ru+=e.faction==='Bandits'?80:0;showFeed('✕  '+entityName(e.name)+' УБИТ · '+factionName(e.faction));audio(70,.14,'triangle',.04)}else audio(55,.08,'sine',.02);break}}}
function update(dt){if(!gameStarted||paused||dead||won)return;elapsed+=dt;player.shootCd=Math.max(0,player.shootCd-dt);player.flash=Math.max(0,player.flash-dt);player.invuln=Math.max(0,player.invuln-dt);if(toastTimer>0&& (toastTimer-=dt)<=0)$('toast').classList.remove('visible');if(bannerTimer>0&&(bannerTimer-=dt)<=0)$('objective-banner').classList.remove('show');let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+input.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+input.y;let len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}let sprint=keys.shift||input.sprint,loadPenalty=clamp((inventoryWeight()-18)/8,0,.35),speed=player.speed*(1-loadPenalty)*(sprint?1.52:1);moveActor(player,dx*speed*dt,dy*speed*dt,player.r);if(player.moving&&!input.hasAimed&&!mouse.active)player.angle=Math.atan2(dy,dx);if(input.aiming&&Math.hypot(input.aimX,input.aimY)>.18){player.angle=Math.atan2(input.aimY,input.aimX);input.hasAimed=true}else if(mouse.active&&(mouse.down||!input.hasAimed)){let worldMouse={x:mouse.x+camera.x,y:mouse.y+camera.y};player.angle=Math.atan2(worldMouse.y-player.y,worldMouse.x-player.x);input.hasAimed=false}if(mouse.down||input.fire)fire();const safeCamp=dist(player,zones[0])<zones[0].r;player.hunger=clamp(player.hunger-dt*(safeCamp?.12:.2)*(sprint?1.12:1),0,100);player.thirst=clamp(player.thirst-dt*(safeCamp?.2:.32)*(sprint?1.18:1),0,100);if(player.hunger<=0||player.thirst<=0){needDamageTimer+=dt;let interval=player.hunger<=0&&player.thirst<=0?3.5:5;if(needDamageTimer>=interval){needDamageTimer=0;player.hp=Math.max(0,player.hp-(player.hunger<=0&&player.thirst<=0?3:2));toast(player.thirst<=0?'ЖАЖДА ИСТОЩАЕТ ТЕБЯ · ИЩИ ВОДУ':'ГОЛОД ОСЛАБЛЯЕТ ТЕБЯ · ИЩИ ПАЁК');if(player.hp<=0){endGame(false);return}}}else needDamageTimer=0;
  // The Zone's A-life: squads keep moving and fighting even when outside the camera.
  for(let e of enemies){if(e.dead)continue;e.alert=Math.max(0,(e.alert||0)-dt);e.attackCd=Math.max(0,(e.attackCd||0)-dt);let d=dist(e,player),hostile=e.faction==='Bandits'||e.faction==='Mutants';if(hostile&&safeCamp&&e.state==='hunt'){e.state='patrol';e.alert=0}if(hostile&&!safeCamp&&d<330){e.state='hunt';e.alert=4}else if(e.state==='hunt'&&e.alert<=0)e.state='patrol';if(e.state==='hunt'&&d>28){let a=Math.atan2(player.y-e.y,player.x-e.x),sp=e.type==='mutant'?(e.name==='pseudodog'?128:e.name==='bloodsucker'?112:e.name==='snork'?96:64):58;e.angle=a;moveActor(e,Math.cos(a)*sp*dt,Math.sin(a)*sp*dt,e.r||11)}else if(e.type==='mutant'&&!safeCamp&&d<31&&e.attackCd<=0&&player.invuln<=0){e.attackCd=.85;player.hp-=e.name==='bloodsucker'?16:11;player.invuln=.45;$('hit-flash').classList.add('active');setTimeout(()=>$('hit-flash').classList.remove('active'),130);if(player.hp<=0)endGame(false)}else if(e.state==='patrol'){if(Math.hypot(e.tx-e.x,e.ty-e.y)<16||rng()<.004){e.tx=clamp(e.x+(rng()-.5)*230,60,W-60);e.ty=clamp(e.y+(rng()-.5)*230,60,H-60)}let a=Math.atan2(e.ty-e.y,e.tx-e.x);e.angle=a;moveActor(e,Math.cos(a)*24*dt,Math.sin(a)*24*dt,e.r||11)}
    if(hostile&&!safeCamp&&e.type!=='mutant'&&d<300&&Math.random()<dt*.55){let a=Math.atan2(player.y-e.y,player.x-e.x);bullets.push({x:e.x,y:e.y,vx:Math.cos(a)*310,vy:Math.sin(a)*310,life:1.2,owner:'enemy',damage:8});e.state='hunt';e.alert=3}
  }
  // Nearby squads and mutants resolve encounters off-camera too; the Zone keeps its own score.
  for(let i=0;i<enemies.length;i++){let a=enemies[i];if(a.dead)continue;for(let j=i+1;j<enemies.length;j++){let b=enemies[j];if(b.dead||dist(a,b)>190)continue;let opposed=a.faction!==b.faction&&(a.faction==='Mutants'||b.faction==='Mutants'||a.faction==='Bandits'||b.faction==='Bandits');if(!opposed)continue;a.state=b.state='engaged';a.target=b;b.target=a;a.alert=b.alert=2;if(Math.random()<dt*.75){let target=Math.random()<.5?a:b;target.hp-=target.type==='mutant'?8:11;if(target.hp<=0){target.dead=true;showFeed(`ЖИЗНЬ ЗОНЫ · ${entityName(target.name)} ПОГИБ: ${factionName(target===a?b.faction:a.faction)}`)}}}}
  for(let b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.owner==='enemy'&&!safeCamp&&dist(b,player)<player.r+4&&player.invuln<=0){b.life=0;player.hp-=b.damage;player.invuln=.32;$('hit-flash').classList.add('active');setTimeout(()=>$('hit-flash').classList.remove('active'),130);audio(68,.12,'sawtooth',.04);if(player.hp<=0)endGame(false)}}
  for(let f of fx)f.life-=dt;for(let i=bullets.length-1;i>=0;i--)if(bullets[i].life<=0)bullets.splice(i,1);for(let i=fx.length-1;i>=0;i--)if(fx[i].life<=0)fx.splice(i,1);
  let danger=dist(player,{x:1540,y:1100});player.rad=clamp(player.rad+(danger<210?dt*1.1:-dt*.35),0,100);if(player.rad>60&&Math.random()<dt*.28){player.hp=Math.max(1,player.hp-1);toast('РАДИАЦИЯ · НАЙДИ УКРЫТИЕ')}
  if(artifact.found&&dist(player,{x:420,y:1480})<100){won=true;endGame(true)}
  updateInteractionPrompt();
  camera.x=clamp(player.x-cw/2,0,W-cw);camera.y=clamp(player.y-ch/2,0,H-ch);updateUI();mapTimer+=dt;if(mapTimer>.25){drawMap();mapTimer=0}
}
function updateInteractionPrompt(){let prompt=$('interaction-prompt'),label=prompt.querySelector('span'),choices=[];for(let g of gates){let d=dist(player,g);if(d<110)choices.push({d,text:'ПЕРЕЙТИ · '+locationName(g.destination)})}for(let n of civilians){let d=dist(player,n);if(d<78)choices.push({d,text:'ПОГОВОРИТЬ · '+entityName(n.name)})}for(let s of stash)if(!s.searched){let d=dist(player,s);if(d<78)choices.push({d,text:'ОБЫСКАТЬ · '+({ 'SUPPLY CRATE':'ЯЩИК С ПРИПАСАМИ','ABANDONED PACK':'БРОШЕННЫЙ РЮКЗАК','STALKER CACHE':'ТАЙНИК СТАЛКЕРА'}[s.kind]||s.kind)})}if(!artifact.found){let d=dist(player,artifact);if(d<98)choices.push({d,text:'ЗАБРАТЬ АРТЕФАКТ'})}choices.sort((a,b)=>a.d-b.d);if(choices.length){label.textContent=choices[0].text;prompt.classList.add('visible')}else prompt.classList.remove('visible')}
