import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true, args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1280,height:800}});
page.on('pageerror', e => console.log('PAGEERROR',e.message));
page.on('console', m => { if(m.type()==='error') console.log('CONSOLE',m.text()); });
await page.goto('http://localhost:8000', {waitUntil:'load'});
await page.locator('#start-button').click();
const state=async(label)=>console.log(label, 'coords=',await page.locator('#map-coords').innerText(),'hp=',await page.locator('#health-value').innerText(),'prompt=',(await page.locator('#interaction-prompt').innerText()).trim(),'mission=',await page.locator('#mission-title').innerText());
const move=async(keys,ms)=>{for(const k of keys) await page.keyboard.down(k); await page.waitForTimeout(ms); for(const k of keys) await page.keyboard.up(k); await page.waitForTimeout(100)};
await state('camp');
await move(['d'],500); await state('toward camp gate');
await page.keyboard.press('e'); await page.waitForTimeout(200); await state('quiet mile');
await move(['d','w'],300); await state('quiet crossing approach');
await page.keyboard.press('e'); await page.waitForTimeout(200); await state('old rail yard');
// Head toward the artifact while aiming away from nearby hostiles.
await move(['d','w'],1300); await state('rail approach');
// Capture a gameplay screenshot before pickup for inspection fallback.
await page.screenshot({path:'/tmp/opencode/rail-approach.png'});
// If close enough, continue in short steps until the pickup prompt appears.
for(let i=0;i<8;i++) { const prompt=(await page.locator('#interaction-prompt').innerText()).trim(); if(prompt.includes('АРТЕФАКТ')) break; await move(['d','w'],250); }
await state('artifact approach');
if((await page.locator('#interaction-prompt').innerText()).includes('АРТЕФАКТ')) { await page.keyboard.press('e'); await page.waitForTimeout(250); }
await state('artifact picked');
console.log('end overlay?',await page.locator('#end-overlay').getAttribute('class'));
await page.screenshot({path:'/tmp/opencode/artifact-phase.png'});
await browser.close();

