import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.route('**/game.js', async route => {
  const response = await route.fetch();
  const js = await response.text();
  const instrumented = js.replace('})();', 'window.__gameTest={player,artifact,gates,enemies,civilians,stash,camera};})();');
  await route.fulfill({ response, body: instrumented });
});
await page.goto('http://localhost:8000');
await page.locator('#start-button').click();
const state = async () => page.evaluate(() => ({
  x: Math.round(window.__gameTest.player.x), y: Math.round(window.__gameTest.player.y),
  hp: Math.round(window.__gameTest.player.hp), ammo: window.__gameTest.player.ammo,
  artifact: window.__gameTest.artifact.found,
  location: document.querySelector('#location-name').textContent,
  prompt: document.querySelector('#prompt-text').textContent,
  victory: !document.querySelector('#end-overlay').classList.contains('hidden'),
  title: document.querySelector('#end-title').textContent
}));
const info = async label => console.log(label, await state());
async function travel(x, y, limit = 180) {
  for (let n = 0; n < limit; n++) {
    const pos = await page.evaluate(() => ({ x: window.__gameTest.player.x, y: window.__gameTest.player.y }));
    const dx = x - pos.x, dy = y - pos.y;
    if (Math.hypot(dx, dy) < 14) return true;
    const key = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'd' : 'a') : (dy > 0 ? 's' : 'w');
    await page.keyboard.down(key);
    await page.waitForTimeout(70);
    await page.keyboard.up(key);
    await page.waitForTimeout(15);
    if (n % 15 === 14) {
      const now = await page.evaluate(() => ({ x: window.__gameTest.player.x, y: window.__gameTest.player.y }));
      if (Math.hypot(now.x - pos.x, now.y - pos.y) < 1) {
        console.log('BLOCKED near', Math.round(now.x), Math.round(now.y), 'target', x, y);
        return false;
      }
    }
  }
  await info('travel timeout');
  return false;
}
const interact = async label => {
  await page.waitForTimeout(100);
  await info(label + ' approach');
  await page.keyboard.press('e');
  await page.waitForTimeout(140);
  await info(label + ' interact');
};
const place = async (x, y) => {
  await page.evaluate(({ x, y }) => { window.__gameTest.player.x = x; window.__gameTest.player.y = y; }, { x, y });
  await page.waitForTimeout(80);
};
try {
  await info('start');
  const routed = await travel(460, 1710) && await travel(650, 1710) && await travel(650, 1480);
  console.log('camp approach route', routed);
  await interact('camp gate');
  if ((await state()).location !== 'THE QUIET MILE') throw new Error('Camp gate did not transition to Quiet Mile');

  await place(1470, 1100);
  await interact('rail gate');
  if ((await state()).location !== 'OLD RAIL YARD') throw new Error('Rail gate did not transition to Old Rail Yard');

  await place(2050, 730);
  await interact('return from rail');
  if ((await state()).location !== 'THE QUIET MILE') throw new Error('Rail return gate did not transition to Quiet Mile');

  // Verify a live firearm hit against the nearby bandit; aim at the target through the real canvas input.
  await place(650, 1370);
  const beforeCombat = await page.evaluate(() => window.__gameTest.enemies.find(e => e.name === 'Rook').hp);
  const aim = await page.evaluate(() => {
    const { camera, enemies } = window.__gameTest;
    const canvas = document.querySelector('#world');
    const rect = canvas.getBoundingClientRect();
    const enemy = enemies.find(e => e.name === 'Rook');
    return { x: rect.left + (enemy.x - camera.x) * rect.width / canvas.width, y: rect.top + (enemy.y - camera.y) * rect.height / canvas.height };
  });
  await page.mouse.move(aim.x, aim.y);
  await page.mouse.down();
  await page.waitForTimeout(240);
  await page.mouse.up();
  await page.waitForTimeout(120);
  const combat = await page.evaluate(() => ({ hp: window.__gameTest.enemies.find(e => e.name === 'Rook').hp, ammo: window.__gameTest.player.ammo }));
  console.log('combat', { before: beforeCombat, ...combat });
  if (!(combat.hp < beforeCombat && combat.ammo < 30)) throw new Error('Weapon did not damage the nearby bandit');

  await place(2200, 555);
  await interact('artifact');
  if (!(await state()).artifact) throw new Error('Artifact was not collected');
  await place(420, 1480);
  await page.waitForTimeout(200);
  await info('camp victory');
  if (!(await state()).victory) throw new Error('Returning to camp did not trigger victory');
  console.log('RESULT: gate transitions, combat damage, artifact pickup, and return-to-camp victory all passed.');
} finally {
  await browser.close();
}

